      "در تمام مراحل، وضعیت واقعی مواد را معیار قرار دهید و فقط به زمان تقریبی تکیه نکنید.",
      "گوشت چرخ کرده را در زمان مناسب به پایه اضافه کنید و چند دقیقه با دقت کار کنید تا طعم اولیه مواد با هم آشنا شود و ساختار اصلی کوفته ریزه شکل بگیرد.",
